module.exports = {
  /**
   * Get local IP address from a given MAC
   *
   * @param device
   * @returns {Promise<string>}
   */
  getDeviceIP(device) {
    const mac = device.extra.extra.staMac.replace(/[^a-fA-F0-9]/g, '');
    const arpItem = this.arpTable.find(
      item => item.mac.replace(/[^a-fA-F0-9]/g, '').toLowerCase() === mac.toLowerCase()
    );
    return arpItem ? arpItem.ip : null;
  },
};
